public record PostSummary(int Id, string Title);

public static class PostQueries
{
    public static async Task<List<PostSummary>> GetPostsWithTitlePrefixAsync(
        BlogContext blogContext,
        string prefix,
        CancellationToken cancellationToken)
    {
        var escapedPrefix = prefix.Replace("\\", "\\\\").Replace("%", "\\%").Replace("_", "\\_");
        var titlePattern = escapedPrefix + "%";

        var postsWithTitlePrefixQuery =
            from post in blogContext.Posts
            where EF.Functions.Like(post.Title, titlePattern, "\\")
            select new PostSummary(post.Id, post.Title);

        return await postsWithTitlePrefixQuery.ToListAsync(cancellationToken);
    }
}
